#!/usr/bin/env Rscript
# Aggregate-only integrity fingerprint; no IDs or scores leave the server.
suppressPackageStartupMessages({library(data.table);library(jsonlite);library(digest)})
args<-commandArgs(TRUE);stopifnot(length(args)==1);work<-normalizePath(args[1]);d<-fread(Sys.getenv('DISCO_ORGAN_INPUT'),colClasses=c(eid='character'));o<-c('tongue','salivary.gland','stomach','adipose.tissue','choroid.plexus','retina','lung','pancreas','kidney','heart.muscle','skin','esophagus','skeletal.muscle','intestine','bone.marrow','liver','brain','lymphoid.tissue');d<-d[order(eid)];z<-as.matrix(d[,..o]);stopifnot(!anyDuplicated(d$eid),all(is.finite(z)));txt<-vapply(seq_len(nrow(d)),function(i)paste(c(d$eid[i],sprintf('%.10f',z[i,])),collapse='|'),'');h<-digest(paste(txt,collapse='\n'),algo='sha256',serialize=FALSE);write_json(list(N=nrow(d),score_fields=o,decimal_digits=10,canonical='lexicographic eid order; each record eid|18scores formatted%.10f; newline joined; aggregate SHA256',core_sha256=h,records_exported=FALSE),file.path(work,'server_core_fingerprint.json'),pretty=TRUE,auto_unbox=TRUE)
